import sys
from itertools import product

n = int(sys.stdin.read().split()[0])
M = 10**9 + 7
if n <= 9:
    cnt = 0
    for s in product(range(4), repeat=n):
        if all(abs(s[i] - s[i + 1]) != 1 for i in range(n - 1)) and s.count(0) % 2 == 1:
            cnt += 1
    print(cnt % M)
else:
    dp = {}
    for c in range(4):
        dp[(c, 1 if c == 0 else 0)] = 1
    for _ in range(n - 1):
        nd = {}
        for (last, par), v in dp.items():
            for c in range(4):
                if abs(c - last) == 1:
                    continue
                k = (c, par ^ (1 if c == 0 else 0))
                nd[k] = (nd.get(k, 0) + v) % M
        dp = nd
    print(sum(v for (l, p), v in dp.items() if p == 1) % M)

